package com.alsafa.native4;

import android.app.Activity;
import android.content.ContentValues;
import android.os.Bundle;
import android.view.View;
import android.widget.EditText;
import android.widget.LinearLayout;
import android.widget.TextView;
import com.alsafa.native4.core.ClosingCarryStore;
import com.alsafa.native4.core.CoreDb;
import com.alsafa.native4.core.CoreOutboxSender;
import com.alsafa.native4.core.DailyClosingStore;
import com.alsafa.native4.core.Native4Services;
import com.alsafa.native4.core.NextDayOpeningStore;
import com.alsafa.native4.sync.OutboxDb;
import com.alsafa.native4.sync.OutboxSender;
import com.alsafa.native4.sync.FirestoreDirectTransport;
import com.google.firebase.auth.FirebaseAuth;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.Locale;

public class MainActivity extends Activity {
 private static final String TEST_STORE="test-native4-android-alpha",DEVICE_ID="native4-android-alpha";
 private TextView status,authStatus,products,sales,repairs,outbox,sectionTitle,sectionSubtitle,saleSelectedProduct,expectedClosing,drawerOut,latestCarryPreview;
 private EditText authEmail,authPassword,productName,productQuantity,productPrice,saleSearch,saleProductId,saleQuantity,salePayment,repairCustomer,repairWatch,repairTotal,repairPayment,closingDay,openingUsd,openingTry,openingSyp,countedUsd,countedTry,countedSyp,carryUsd,carryTry,carrySyp,closingNotes;
 private LinearLayout testPanel,saleSearchResults,closingPanel,dynamicPanelHost;
 private OutboxDb db;private CoreDb coreDb;private Native4Services services;private DailyClosingStore closingStore;private NextDayOpeningStore nextDayStore;private PurchasePanelBinder purchasePanel;private CoreSalePanelBinder salePanel;private CoreRepairPanelBinder repairPanel;private CoreProductPanelBinder productPanel;private OnlineSalePanelBinder onlineSalePanel;private DirectPartSalePanelBinder directPartSalePanel;private SimpleModePanelBinder simpleModePanel;private CashPanelBinder cashPanel;private ReportPanelBinder reportPanel;private FirebaseAuth auth;
 @Override public void onCreate(Bundle state){super.onCreate(state);Native4Safety.requireIsolatedStore(TEST_STORE);setContentView(R.layout.activity_main);db=new OutboxDb(this);recoverMissingDefaultDatabaseFailures();db.recoverInterrupted();coreDb=new CoreDb(this);recoverCoreInterrupted();services=new Native4Services(coreDb,DEVICE_ID);closingStore=services.closing;nextDayStore=services.nextDayOpening;auth=FirebaseAuth.getInstance();status=findViewById(R.id.status);authStatus=findViewById(R.id.authStatus);products=findViewById(R.id.products);sales=findViewById(R.id.sales);repairs=findViewById(R.id.repairs);outbox=findViewById(R.id.outbox);sectionTitle=findViewById(R.id.sectionTitle);sectionSubtitle=findViewById(R.id.sectionSubtitle);testPanel=findViewById(R.id.testPanel);dynamicPanelHost=findViewById(R.id.dynamicPanelHost);saleSearchResults=findViewById(R.id.saleSearchResults);saleSelectedProduct=findViewById(R.id.saleSelectedProduct);closingPanel=findViewById(R.id.closingPanel);expectedClosing=findViewById(R.id.expectedClosing);drawerOut=findViewById(R.id.drawerOut);latestCarryPreview=findViewById(R.id.latestCarryPreview);authEmail=findViewById(R.id.authEmail);authPassword=findViewById(R.id.authPassword);productName=findViewById(R.id.productName);productQuantity=findViewById(R.id.productQuantity);productPrice=findViewById(R.id.productPrice);saleSearch=findViewById(R.id.saleSearch);saleProductId=findViewById(R.id.saleProductId);saleQuantity=findViewById(R.id.saleQuantity);salePayment=findViewById(R.id.salePayment);repairCustomer=findViewById(R.id.repairCustomer);repairWatch=findViewById(R.id.repairWatch);repairTotal=findViewById(R.id.repairTotal);repairPayment=findViewById(R.id.repairPayment);closingDay=findViewById(R.id.closingDay);openingUsd=findViewById(R.id.openingUsd);openingTry=findViewById(R.id.openingTry);openingSyp=findViewById(R.id.openingSyp);countedUsd=findViewById(R.id.countedUsd);countedTry=findViewById(R.id.countedTry);countedSyp=findViewById(R.id.countedSyp);carryUsd=findViewById(R.id.carryUsd);carryTry=findViewById(R.id.carryTry);carrySyp=findViewById(R.id.carrySyp);closingNotes=findViewById(R.id.closingNotes);closingDay.setText(new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date()));purchasePanel=new PurchasePanelBinder(this,services,status);salePanel=new CoreSalePanelBinder(this,services,status);repairPanel=new CoreRepairPanelBinder(this,services,status);productPanel=new CoreProductPanelBinder(this,services,status);onlineSalePanel=new OnlineSalePanelBinder(this,services,status,dynamicPanelHost);directPartSalePanel=new DirectPartSalePanelBinder(this,services,status,dynamicPanelHost);cashPanel=new CashPanelBinder(this,services,status,dynamicPanelHost);reportPanel=new ReportPanelBinder(this,services,status,dynamicPanelHost);simpleModePanel=new SimpleModePanelBinder(this,dynamicPanelHost,new SimpleModePanelBinder.Actions(){public void openSale(){showSection(HomeSection.SALES);}public void openRepair(){showSection(HomeSection.REPAIRS);}public void openDirectPartSale(){showSection(HomeSection.DIRECT_PART_SALES);}public void openClosing(){showSection(HomeSection.CLOSING);}});bindSection(R.id.navSimple,HomeSection.SIMPLE);bindSection(R.id.navSales,HomeSection.SALES);bindSection(R.id.navOnlineSales,HomeSection.ONLINE_SALES);bindSection(R.id.navDirectPartSales,HomeSection.DIRECT_PART_SALES);bindSection(R.id.navRepairs,HomeSection.REPAIRS);bindSection(R.id.navProducts,HomeSection.PRODUCTS);bindSection(R.id.navPurchases,HomeSection.PURCHASES);bindSection(R.id.navCash,HomeSection.CASH);bindSection(R.id.navClosing,HomeSection.CLOSING);bindSection(R.id.navReports,HomeSection.REPORTS);bindSection(R.id.navSettings,HomeSection.SETTINGS);findViewById(R.id.signIn).setOnClickListener(v->signIn());findViewById(R.id.signOut).setOnClickListener(v->{auth.signOut();authPassword.setText("");status.setText("تم تسجيل الخروج");refresh();});findViewById(R.id.sendOutbox).setOnClickListener(v->sendOutbox());findViewById(R.id.openWorkDay).setOnClickListener(v->openWorkDay());findViewById(R.id.useLatestCarry).setOnClickListener(v->openFromLatestCarry());findViewById(R.id.refreshExpected).setOnClickListener(v->refreshExpected());findViewById(R.id.calcDrawerOut).setOnClickListener(v->calculateDrawerOut());findViewById(R.id.closeWorkDay).setOnClickListener(v->closeWorkDay());showSection(HomeSection.SIMPLE);refresh();}
 private void recoverMissingDefaultDatabaseFailures(){ContentValues v=new ContentValues();v.put("state","FAILED_RETRYABLE");v.put("last_error","تم إنشاء Firestore (default) ونشر القواعد؛ أعيدت العملية القديمة للمحاولة بنفس operationId");db.getWritableDatabase().update("outbox",v,"state='FAILED_PERMANENT' AND last_error LIKE ?",new String[]{"%database (default) does not exist for project alsafa-native%"});}
 private void recoverCoreInterrupted(){ContentValues v=new ContentValues();v.put("state","RETRY");v.put("last_error","استعادة آمنة بعد توقف التطبيق أثناء الإرسال");coreDb.db().update("outbox",v,"state='SENDING'",null);}
 private void bindSection(int id,HomeSection section){findViewById(id).setOnClickListener(v->showSection(section));}
 private void showSection(HomeSection section){sectionTitle.setText(section.title);sectionSubtitle.setText(section.subtitle);boolean simple=section==HomeSection.SIMPLE,coreEntry=section==HomeSection.SALES||section==HomeSection.REPAIRS||section==HomeSection.PRODUCTS,purchases=section==HomeSection.PURCHASES,closing=section==HomeSection.CLOSING,online=section==HomeSection.ONLINE_SALES,directParts=section==HomeSection.DIRECT_PART_SALES,cash=section==HomeSection.CASH,reports=section==HomeSection.REPORTS;testPanel.setVisibility(coreEntry?View.VISIBLE:View.GONE);purchasePanel.show(purchases);closingPanel.setVisibility(closing?View.VISIBLE:View.GONE);simpleModePanel.show(simple);onlineSalePanel.show(online);directPartSalePanel.show(directParts);cashPanel.show(cash);reportPanel.show(reports);if(!purchases)status.setText(simple?"الوضع المبسط يستخدم نفس المبيع والصيانة والصندوق والمزامنة دون قاعدة منفصلة":section==HomeSection.SALES?"المبيع داخل المتجر يعمل على CoreDb المحلي + Outbox":section==HomeSection.ONLINE_SALES?"بيع الإنترنت: الشحن والعربون والتحصيل والمتبقي على نفس الفاتورة":section==HomeSection.DIRECT_PART_SALES?"بيع قطع الصيانة أو خدمة سريعة بدون استلام ساعة":section==HomeSection.REPAIRS?"الصيانة تعمل على CoreDb المحلي + Outbox":section==HomeSection.PRODUCTS?"المنتجات تعمل على CoreDb + Outbox مع تنبيه التكرار دون حذف أو استبدال":cash?"الصناديق: نقل وسحوبات مع فصل USD / TRY / SYP دون تحويل ضمني":reports?"تقارير اليوم والشهر والسنة — قراءة فقط من CoreDb":closing?"الإقفال يعمل على CoreDb المحلي — العملات منفصلة":"هذه الوحدة ضمن بناء v4.1 ولم تُفعّل للكتابة بعد");if(closing){refreshCarryPreview();refreshExpectedQuietly();}}
 private void signIn(){String email=authEmail.getText().toString().trim(),password=authPassword.getText().toString();if(email.isEmpty()||password.isEmpty()){status.setText("أدخل بريد وكلمة مرور مستخدم الاختبار");return;}status.setText("جاري تسجيل الدخول...");auth.signInWithEmailAndPassword(email,password).addOnCompleteListener(this,t->{authPassword.setText("");status.setText(t.isSuccessful()?"✓ تم تسجيل الدخول إلى Firebase التجريبي":"فشل تسجيل الدخول: "+(t.getException()==null?"خطأ غير معروف":t.getException().getClass().getSimpleName()));refresh();});}
 private void sendOutbox(){Native4Safety.requireIsolatedStore(TEST_STORE);if(auth.getCurrentUser()==null){status.setText("سجل الدخول أولاً؛ لم يتم إرسال شيء");return;}status.setText("جاري إرسال Outbox القديم وCoreDb مباشرة إلى Firebase...");new Thread(()->{try{FirestoreDirectTransport transport=new FirestoreDirectTransport();int alphaConfirmed=new OutboxSender(db,transport,TEST_STORE).drainOnce();int coreConfirmed=new CoreOutboxSender(coreDb,transport,TEST_STORE).drainOnce();runOnUiThread(()->{status.setText("انتهت محاولة Firebase المباشرة. المؤكد: "+(alphaConfirmed+coreConfirmed)+" (Alpha "+alphaConfirmed+" + Core "+coreConfirmed+")");refresh();});}catch(Exception e){runOnUiThread(()->{status.setText("تعذر الإرسال: "+e.getClass().getSimpleName()+" — العمليات المحلية محفوظة للمحاولة لاحقاً");refresh();});}}).start();}
 private void openWorkDay(){try{closingStore.open(day(),money(openingUsd),money(openingTry),money(openingSyp),"");status.setText("✓ تم فتح أول يوم/فتح يدوي وحفظ المدوّر محلياً + Outbox");refreshExpected();refresh();}catch(Exception e){status.setText("لم يُفتح يوم العمل: "+message(e));}}
 private void openFromLatestCarry(){try{ClosingCarryStore.Carry c=nextDayStore.open(day());openingUsd.setText(fmt(c.usd));openingTry.setText(fmt(c.tryAmount));openingSyp.setText(fmt(c.syp));status.setText("✓ تم فتح اليوم من مدوّر إقفال "+c.businessDay+" فقط");refreshCarryPreview();refreshExpected();refresh();}catch(Exception e){status.setText("لم يُفتح اليوم من المدوّر: "+message(e));}}
 private void refreshCarryPreview(){ClosingCarryStore.Carry c=nextDayStore.preview();if(c==null){latestCarryPreview.setText("آخر مدوّر محفوظ: لا يوجد إقفال سابق");return;}latestCarryPreview.setText("آخر مدوّر محفوظ من "+c.businessDay+" — USD: "+fmt(c.usd)+" | TRY: "+fmt(c.tryAmount)+" | SYP: "+fmt(c.syp));}
 private void refreshExpected(){try{DailyClosingStore.Expected e=closingStore.expected(day());expectedClosing.setText("المتوقع — USD: "+fmt(e.usd)+" | TRY: "+fmt(e.tryAmount)+" | SYP: "+fmt(e.syp));status.setText("✓ تم تحديث المتوقع من مدوّر البداية وحركات هذا اليوم فقط");}catch(Exception e){expectedClosing.setText("المتوقع: —");status.setText("تعذر حساب المتوقع: "+message(e));}}
 private void refreshExpectedQuietly(){try{DailyClosingStore.Expected e=closingStore.expected(day());expectedClosing.setText("المتوقع — USD: "+fmt(e.usd)+" | TRY: "+fmt(e.tryAmount)+" | SYP: "+fmt(e.syp));}catch(Exception ignored){expectedClosing.setText("المتوقع: افتح يوم العمل أولاً");}}
 private void calculateDrawerOut(){try{double u=drawer(money(countedUsd),money(carryUsd)),t=drawer(money(countedTry),money(carryTry)),s=drawer(money(countedSyp),money(carrySyp));drawerOut.setText("الخارج من الدرج — USD: "+fmt(u)+" | TRY: "+fmt(t)+" | SYP: "+fmt(s));status.setText("✓ تم الحساب دون تحويل بين العملات");}catch(Exception e){status.setText("تعذر الحساب: "+message(e));}}
 private void closeWorkDay(){try{double cu=money(countedUsd),ct=money(countedTry),cs=money(countedSyp),ku=money(carryUsd),kt=money(carryTry),ks=money(carrySyp);String id=closingStore.close(day(),cu,ct,cs,ku,kt,ks,closingNotes.getText().toString());drawerOut.setText("الخارج من الدرج — USD: "+fmt(drawer(cu,ku))+" | TRY: "+fmt(drawer(ct,kt))+" | SYP: "+fmt(drawer(cs,ks)));status.setText("✓ تم إقفال اليوم محلياً وتثبيت المدوّر. المرجع: "+id);expectedClosing.setText("اليوم مقفل — المدوّر المحفوظ هو فقط ما سيبدأ به اليوم التالي");refreshCarryPreview();refresh();}catch(Exception e){status.setText("لم يتم الإقفال: "+message(e));}}
 private String day(){return closingDay.getText().toString().trim();}private static double money(EditText e){String v=e.getText().toString().trim();return v.isEmpty()?0:Double.parseDouble(v);}private static double drawer(double counted,double carry){if(!Double.isFinite(counted)||!Double.isFinite(carry)||counted<0||carry<0||carry>counted)throw new IllegalArgumentException("المدوّر يجب أن يكون بين صفر والمبلغ المعدود");return counted-carry;}private static String fmt(double v){return String.format(Locale.US,"%.2f",v);}private static String message(Exception e){return e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}
 private int corePendingCount(){try(android.database.Cursor c=coreDb.db().rawQuery("SELECT COUNT(*) FROM outbox WHERE state IN ('PENDING','RETRY','SENDING')",null)){return c.moveToFirst()?c.getInt(0):0;}}
 private int coreProductCount(){try(android.database.Cursor c=coreDb.db().rawQuery("SELECT COUNT(*) FROM products WHERE deleted_at IS NULL",null)){return c.moveToFirst()?c.getInt(0):0;}}
 private void refresh(){authStatus.setText(auth.getCurrentUser()==null?"Firebase Auth: غير مسجل":"Firebase Auth: مسجل — "+auth.getCurrentUser().getEmail());products.setText("منتجات Core: "+coreProductCount());sales.setText(db.salesSummary());repairs.setText(db.repairsSummary());outbox.setText("عمليات بانتظار التأكيد: "+(db.pendingCount()+corePendingCount())+" — Alpha: "+db.pendingCount()+" | Core: "+corePendingCount()+"\n\n"+db.outboxSummary());}
}
